import React, { useState, useEffect } from "react";

function App() {
  const [users, setUsers] = useState([]);
  const [name, setName] = useState("");
  const [age, setAge] = useState("");

  const [selectedUserId, setSelectedUserId] = useState("");
  const [runs, setRuns] = useState([]);

  const [runDate, setRunDate] = useState("");
  const [runTime, setRunTime] = useState("");
  const [runDistance, setRunDistance] = useState("");

  useEffect(() => {
    fetchUsers();
  }, []);

  async function fetchUsers() {
    const res = await fetch("/users");
    if (res.ok) {
      const data = await res.json();
      setUsers(data.users);
    }
  }

  async function addUser(e) {
    e.preventDefault();
    const res = await fetch("/user", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ name, age: Number(age) }),
    });

    if (res.ok) {
      setName("");
      setAge("");
      fetchUsers();
    } else {
      alert("Invalid age!");
    }
  }

  async function selectUser(id) {
    setSelectedUserId(id);
    const res = await fetch(`/runs/${id}`);
    if (res.ok) {
      const data = await res.json();
      setRuns(data.runs);
    }
  }

  async function deleteUser(id) {
    const confirm = window.confirm("Delete user?");
    if (!confirm) return;

    const res = await fetch(`/user/${id}`, { method: "DELETE" });

    if (res.ok) {
      if (id === selectedUserId) {
        setSelectedUserId("");
        setRuns([]);
      }
      fetchUsers();
    }
  }

  async function addRun(e) {
    e.preventDefault();
    if (!selectedUserId) return alert("Select a user first");

    const res = await fetch(`/runs/${selectedUserId}`, {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        date: runDate,
        time: runTime,
        distance: runDistance,
      }),
    });

    if (res.ok) {
      setRunDate("");
      setRunTime("");
      setRunDistance("");
      selectUser(selectedUserId);
    } else {
      alert("Invalid run data");
    }
  }

  return (
    <div style={{ padding: 20 }}>
      <h1>Run Tracker</h1>

      {/* Add User */}
      <h2>Add User</h2>
      <form onSubmit={addUser}>
        <input
          placeholder="Name"
          value={name}
          onChange={(e) => setName(e.target.value)}
        />
        <input
          placeholder="Age"
          value={age}
          type="number"
          onChange={(e) => setAge(e.target.value)}
        />
        <button type="submit">Add</button>
      </form>

      {/* Users List */}
      <h2>Users</h2>
      <ul>
        {users.map((u) => (
          <li key={u.id}>
            {u.name} (age {u.age})
            <button onClick={() => selectUser(u.id)}>Select</button>
            <button onClick={() => deleteUser(u.id)}>Delete</button>
          </li>
        ))}
      </ul>

      {/* Runs */}
      <h2>User Runs</h2>
      {selectedUserId ? (
        <div>
          <p>Selected User: {selectedUserId}</p>

          <form onSubmit={addRun}>
            <input
              placeholder="Date"
              value={runDate}
              onChange={(e) => setRunDate(e.target.value)}
            />
            <input
              placeholder="Time"
              value={runTime}
              onChange={(e) => setRunTime(e.target.value)}
            />
            <input
              placeholder="Distance"
              value={runDistance}
              onChange={(e) => setRunDistance(e.target.value)}
            />
            <button type="submit">Add Run</button>
          </form>

          <ul>
            {runs.map((r, i) => (
              <li key={i}>
                {r.date} — {r.time} — {r.distance}
              </li>
            ))}
          </ul>
        </div>
      ) : (
        <p>No user selected.</p>
      )}
    </div>
  );
}

export default App;
